from format_lecon import Lesson,paras,steps,table
from medicaments import cycloplegie,atropine
l=Lesson('Ésotropie accommodative',1);cy=cycloplegie(l);at=atropine(l)
l.add('L’{ésotropie accommodative est une convergence liée à l’effort de mise au point}. La correction de l’hypermétropie réduit cette composante. Une déviation persistante sous correction complète indique une composante résiduelle à caractériser.',paras('Le Royal College of Ophthalmologists, en 2012, définit la forme pleinement accommodative par un désalignement acquis redressé par la correction de l’hypermétropie. La forme partiellement accommodative s’améliore sans disparaître complètement.', 'Ne pas confondre le mécanisme accommodatif avec toute ésotropie de l’enfant. Une paralysie du VI, une ésotropie infantile, une atteinte sensorielle ou une cause neurologique peuvent produire une convergence apparente. La direction ne suffit pas au diagnostic.'),(1,3))
l.add('Le {début survient souvent dans la petite enfance}. Les antécédents familiaux et l’hypermétropie orientent. Sans prise en charge, une préférence de fixation peut favoriser une amblyopie.',paras('La brochure HUG décrit une apparition habituelle entre 18 mois et 2 ans ; le guide britannique de 2012 cite généralement 2–5 ans pour la forme pleinement accommodative. Ces fenêtres descriptives se recouvrent imparfaitement et ne doivent pas devenir des limites d’exclusion.', 'Aucune incidence suisse récente propre à cette forme n’a été trouvée dans les sources consultées. Le pourcentage de 36,4 % des ésotropies infantiles cité dans le guide britannique provient de sa bibliographie et n’est pas repris comme statistique suisse.', 'Le port de lunettes peut rester nécessaire longtemps. Une minorité perd le contrôle malgré une correction apparemment adaptée, ce qui impose de réexaminer réfraction, observance et vision binoculaire. Un alignement sous lunettes n’équivaut pas à une disparition de l’hypermétropie.'),(1,3))
l.add('Le {couplage accommodation-convergence explique l’effet des lunettes}. L’œil hypermétrope doit accommoder davantage pour obtenir une image nette. Les verres adaptés diminuent cet effort et la convergence qui l’accompagne.',table(['Perturbation','Comment l’objectiver','Traitement dirigé'],[['La réfraction hypermétropique exige une accommodation excessive.','Mesurer la réfraction sous cycloplégie puis l’angle avec la correction.','Les verres positifs réduisent l’effort de mise au point.'],['La fusion ne compense pas toute la déviation.','Comparer les angles de loin et de près et la vision binoculaire.','Adapter la stratégie optique et discuter la composante non accommodative.'],['Une entrée visuelle asymétrique perturbe le développement.','Comparer l’acuité corrigée de chaque œil et la fixation.','Traiter l’amblyopie en plus de la réfraction.']])+paras('Une déviation de près importante peut faire discuter un rapport élevé entre convergence accommodative et accommodation. Le spécialiste mesure ce rapport ; il n’est pas déduit d’une seule photographie. Des bifocaux ou d’autres moyens se discutent dans des profils sélectionnés, sans prescription automatique.'),(1,3,6))
l.add('La {démarche élimine une cause organique ou neurologique avant de conclure}. Une leucocorie ou une baisse de vision inhabituelle impose un examen urgent. Une limitation d’abduction ou des symptômes neurologiques relancent le bilan.',paras('Le rétinoblastome ou une autre atteinte rétinienne peut causer une convergence sensorielle : vérifier reflet rouge et fond d’œil. Ne pas prescrire seulement un cache devant un œil dévié qui voit mal.', 'La paralysie du VI limite réellement l’abduction et ne se résume pas à un effort accommodatif. L’ésotropie infantile est installée très tôt et peut donner une pseudo-limitation par fixation croisée. Le syndrome de Duane associe une anomalie motrice congénitale et une rétraction du globe.', 'Un début aigu avec céphalée, vomissement ou ataxie impose l’orientation immédiate prévue par NICE. Une réponse partielle aux lunettes n’annule pas ces alarmes.'),(3,4,6,9,10))
l.add('L’{interrogatoire recherche les circonstances de convergence et les traitements antérieurs}. Préciser début, intermittence et différence entre près et loin. Les photographies et la correction portée aident à reconstituer l’évolution.',paras('Demander si l’œil dévie pendant une activité de près, à la fatigue ou sans lunettes. Une histoire familiale augmente la plausibilité sans prouver le mécanisme. Recueillir les prescriptions antérieures et le port réel plutôt que supposer une observance parfaite.', 'Rechercher préférence d’un œil, fermeture d’un œil, gêne à la lecture, torticolis et plainte visuelle. Une absence de plainte ne renseigne pas correctement sur l’acuité de chaque œil.', 'Demander aussi douleur, céphalée, vomissements et baisse visuelle récente. Ces signes ne sont pas expliqués par défaut par une hypermétropie connue.'),(1,3,4))
l.add('L’{examen documente le résultat avec et sans correction}. Mesurer chaque acuité et rechercher une préférence de fixation. Comparer l’alignement de loin et de près avec une cible adaptée.',paras('Normalement, une fixation attentive reste stable et les mouvements sont complets. Le test à l’écran montre la tropie ; l’alternance avec prismes quantifie la déviation totale. Noter lunettes, distance et coopération pour rendre les mesures comparables.', 'Les ductions doivent pouvoir être complètes. Une limitation vraie, une anomalie pupillaire ou un fond d’œil anormal conduit à une autre exploration. Examiner la correction elle-même : centrage, ajustement et tendance de l’enfant à regarder au-dessus des verres.', 'La stéréoscopie et les réserves de fusion complètent le bilan lorsqu’elles sont mesurables. Un petit angle résiduel peut conserver une vision binoculaire anormale ; il ne doit pas être ignoré sur le seul aspect esthétique.'),(1,3,6))
l.add('Les {profils cliniques distinguent correction complète et composante résiduelle}. La mesure sous lunettes est déterminante. Une différence près-loin nécessite une analyse spécifique.',paras('7.1. Dans la forme pleinement accommodative, la correction rétablit l’alignement ou un contrôle compatible avec la fusion. Les symptômes et le test à l’écran s’améliorent sous lunettes.', '7.2. Dans la forme partiellement accommodative, une tropie persiste sous correction adéquate. Rechercher réfraction incomplète, défaut de port et amblyopie avant de conclure à une composante chirurgicale.', '7.3. Dans un excès de convergence de près, les angles diffèrent selon la fixation. Le bilan orthoptique mesure cette différence et le rôle de l’accommodation ; il ne suffit pas de voir la déviation sur une photo rapprochée.'),(3,))
l.add('Le {diagnostic repose sur une réponse objectivée à la correction}. Une hypermétropie seule ne prouve pas le mécanisme du strabisme. Un contrôle répété permet de classer la composante persistante.',paras('Selon le guide RCOphth de 2012, la correction complète de l’hypermétropie mesurée sous cycloplégie constitue la référence thérapeutique et diagnostique de la composante accommodative. La réponse est mesurée sous correction effectivement portée.', 'Ne pas imposer un seuil unique de dioptries hypermétropiques pour toutes les formes. La comparaison près-loin, l’intégrité oculaire et la qualité de la cycloplégie comptent. Une forme brutale ou atypique peut nécessiter un bilan même si une hypermétropie est présente.'),(3,6))
l.add('Les {explorations complètent une évaluation surtout clinique}. La réfraction cycloplégique est essentielle chez l’enfant. Les examens neurologiques ou orbitaires répondent aux anomalies associées.',paras('9.a. Le bilan ophtalmologique et orthoptique sous correction est la référence ; aucun test sanguin ne confirme l’ésotropie accommodative.', '9.b. La réfraction objective avec cycloplégie précise la puissance nécessaire. Les modalités et risques suisses sont détaillés ici : '+cy, '9.c. Un examen initial peu fiable est répété avec une méthode adaptée. Une mesure automatique sans cycloplégie ne remplace pas une réfraction précise lorsque la clinique ne concorde pas.', '9.d. Une imagerie est discutée en cas de limitation, début inhabituel, baisse visuelle inexpliquée ou signe neurologique. Elle n’est pas systématique dans une forme typique correctement évaluée.')+table(['Résultat','Signification','Décision'],[['L’angle disparaît sous lunettes.','La composante accommodative explique l’essentiel de la déviation.','Poursuivre le port et contrôler acuité et fusion.'],['L’angle diminue mais persiste.','Une correction insuffisante ou une composante résiduelle est possible.','Vérifier réfraction et port avant de décider une autre intervention.'],['L’acuité ne progresse pas malgré un traitement suivi.','Une amblyopie réfractaire ou une autre atteinte est possible.','Répéter réfraction et examen organique.']]),(3,6,7))
l.add('L’{algorithme commence par les alarmes puis teste le mécanisme optique}. Corriger la réfraction et surveiller la vision. Décider du traitement résiduel après réévaluation.',steps('Écarter leucocorie, déficit moteur véritable et signes neurologiques urgents.', 'Mesurer réfraction sous cycloplégie, acuités et angles de loin et de près.', 'Prescrire la correction complète adaptée, expliquer le port et fixer un contrôle.', 'Traiter l’amblyopie lorsqu’elle est identifiée, sans attendre indéfiniment une amélioration spontanée.', 'Si déviation résiduelle, vérifier lunettes, coopération et réfraction avant de discuter bifocaux, prismes ou chirurgie selon le profil.'),(1,3,6))
l.add('La {prise en charge conserve les lunettes comme traitement du mécanisme}. L’amblyopie demande une stratégie distincte. Une chirurgie éventuelle vise la composante qui persiste sous correction.',paras('11.A. Suivre l’acuité corrigée de chaque œil, l’angle sous lunettes et le fonctionnement binoculaire. Le but est un développement visuel utile et une déviation contrôlée, sans promettre l’arrêt des lunettes.', '11.B. Adapter la monture et expliquer le port quotidien. Une période d’adaptation réfractive permet parfois d’améliorer l’acuité avec les lunettes seules ; le contrôle détermine quand ajouter ou ajuster l’occlusion. Si une pénalisation pharmacologique est retenue : '+at, '11.C. Une baisse visuelle inhabituelle ou une alarme neurologique n’attend pas la fin du traitement d’amblyopie. Réorienter vers le bilan causal. Une chirurgie n’est pas le traitement initial de la composante pleinement corrigée par les lunettes.', '11.D. Le rythme du suivi dépend de l’âge et de la modification thérapeutique. Le guide britannique propose un premier contrôle habituel vers six semaines après prescription et une réfraction annuelle, plus tôt en cas de mauvaise réponse ; ces repères sont individualisés en Suisse. Le retour à domicile suppose compréhension des consignes, accès au contrôle et connaissance des signes d’alerte.', 'Surveiller aussi l’œil pénalisé et la tolérance des dispositifs. Chez la personne enceinte ou allaitante et en cas de comorbidité, appliquer les précautions de la notice si un collyre est nécessaire. Ne pas interrompre ou intensifier seul le traitement à partir d’une amélioration esthétique.'),(1,3,6,8))
l.add('La {prévention repose sur la détection de l’amblyopie et l’observance}. Informer l’entourage des signes de déviation même intermittente. Maintenir les contrôles après amélioration.',paras('La prévention primaire n’offre pas de moyen démontré pour supprimer l’hypermétropie familiale. La prévention secondaire repose sur les contrôles visuels précoces et l’orientation lorsqu’un strabisme est observé.', 'La prévention tertiaire surveille récidive, amblyopie et difficulté de port. Une explication à l’école et un choix de monture acceptable facilitent le traitement. Une gêne nouvelle ou une baisse de vision impose une consultation anticipée.'),(1,2,6))
l.add('Les {points clés distinguent correction optique et guérison anatomique}. Les lunettes réduisent l’effort accommodatif. La vision de chaque œil et l’angle résiduel déterminent la suite.',paras('Une convergence n’est pas toujours accommodative. Une correction efficace ne dispense pas du fond d’œil initial. Une chirurgie ne remplace pas le port de lunettes quand l’hypermétropie persiste. Une mauvaise réponse demande une réévaluation, pas seulement davantage d’occlusion.'),(1,3,6))
l.quiz([('Toute ésotropie est-elle accommodative ?','Non ; le mécanisme doit être démontré.'),('Quel examen précise l’hypermétropie chez l’enfant ?','La réfraction sous cycloplégie.'),('Une pupille dilatée prouve-t-elle une cycloplégie complète ?','Non ; il faut apprécier la qualité de l’examen réfractif.'),('La forme pleinement accommodative reste-t-elle déviée sous correction adéquate ?','L’alignement est rétabli ou contrôlé ; une tropie persistante doit être caractérisée.'),('Faut-il ignorer une déviation de près ?','Non ; comparer près et loin.'),('Les lunettes seules peuvent-elles améliorer une amblyopie ?','Oui, mais la réponse doit être contrôlée.'),('Le cache remplace-t-il le fond d’œil ?','Non.'),('La chirurgie corrige-t-elle l’hypermétropie ?','Non.'),('Peut-on arrêter les lunettes parce que les yeux semblent droits ?','Non, l’alignement peut justement dépendre des lunettes.'),('Cyclogyl est-il autorisé avant un an dans la notice lue ?','Non.'),('L’atropine utilisée pour pénaliser l’œil fixateur exige-t-elle une surveillance ?','Oui, de la tolérance et de la vision des deux yeux.'),('L’âge décrit dans les brochures est-il un critère d’exclusion absolu ?','Non.'),('Que faire si la vision ne s’améliore pas malgré une bonne observance ?','Répéter la réfraction et rechercher une autre cause.'),('Une apparition aiguë avec vomissements attend-elle le contrôle optique ?','Non ; elle impose une évaluation immédiate.')],(1,3,4,6,7,8))
l.write()
